import { ADVANCED_TRACKS } from './advanced_placement.mjs?v=advanced20261027';
export const LEVEL_GOALS = {
 s1:['招呼與自我介紹','辨識字母、數字與基礎字詞'],s2:['描述生活作息','用簡單句點餐與詢問'],s3:['介紹家人與興趣','說明時間、位置與能力'],s4:['在城市與旅途中溝通','比較事物並敘述經驗'],s5:['掌握國中核心句型','理解短文與日常對話'],s6:['整合時態與複句','從閱讀線索推論意思'],s7:['運用高中核心文法','表達理由與組織段落'],s8:['辨析長句與語意','整合閱讀、情境與學術字詞'],s9:['挑戰大考與國際題型','分析論點、推論與進階用法']
};
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function courseAtlas(course,game) {
 return `<details class="course-atlas card"><summary>🗺️ 展開全部程度與課程 · 9 段 / ${course.index.sections.reduce((n,s)=>n+s.units.length,0)} 單元</summary><p class="muted small">第 1–8 段（含高中）全部開放，依需要任選。綠色勾選表示實際學過，開放不等於完成；金冠需另過挑戰。</p><div class="atlas-grid">${course.index.sections.map(s=>`<article class="atlas-level"><p class="eyebrow">第 ${s.no} 段 · ${esc(s.level)}</p><h3>${esc(s.title)}</h3><p class="atlas-goals">${LEVEL_GOALS[s.id].map(esc).join(' · ')}</p><p class="small muted">${s.units.length} 單元 · ${s.units.reduce((n,u)=>n+u.nodes.length,0)} 關 · ${game.trackUnlocked(s.id)?'自由選擇':'可用跳級測驗前往'}</p><button class="btn small" data-act="track" data-id="${s.id}">選擇這一段 →</button><details><summary>展開 ${s.units.length} 個單元</summary><div class="atlas-units">${s.units.map(u=>`<button data-act="unit-select" data-id="${s.id}" data-unit="${u.id}">${esc(u.icon)} ${esc(u.title)} <small>${u.nodes.length} 關</small></button>`).join('')}</div></details></article>`).join('')}</div><h3>學術與推理進階方向</h3><p class="muted small">SAT、GRE、GMAT 依不同能力方向展開，並非同一條考試分數階梯。</p><div class="atlas-grid">${ADVANCED_TRACKS.map(t=>`<article class="atlas-level"><h3>${esc(t.title)}</h3><p class="atlas-goals">${esc(t.focus)}</p><button class="btn small" data-act="track" data-id="${t.id}">展開課程 →</button></article>`).join('')}</div></details>`;
}
